-- Нормализуем один раз при изменении строки, а не при чтении каждого совпадения.
ALTER TABLE contents ADD COLUMN search_text text
 GENERATED ALWAYS AS (space_search_fold_v1(text)) STORED;

-- Двухсимвольные запросы поддерживаются отдельно; для длинных используются триграммы.
CREATE FUNCTION space_search_terms_v1(value text, min_size int, max_size int) RETURNS text[]
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE RETURN (
 WITH chars AS MATERIALIZED (SELECT regexp_split_to_array(value,'') AS c)
 SELECT COALESCE(array_agg(n::text || ':' || array_to_string(c[i:i+n-1],'')),ARRAY[]::text[])
 FROM chars CROSS JOIN generate_series(min_size,max_size) AS n
 CROSS JOIN LATERAL generate_series(1,cardinality(c)-n+1) AS i
);

CREATE INDEX contents_search_terms_v1 ON contents
 USING gin (space_search_terms_v1(search_text,2,3)) WHERE NOT deleted;
